using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SemsApi.DTO.Evaluation;
using SemsApi.Interfaces;

namespace SemsApi.Controllers
{
    /// <summary>
    /// CRUD for the questions (TeacherEvaluationResult) inside a category.
    /// All logic lives in IQuestionService; this controller only handles HTTP concerns.
    /// QuestionId is generated by the database when a question is added.
    /// </summary>
    [ApiController]
    [Authorize(Roles = "QA,Admin")]
    [Route("api/evaluation/categories/{categoryId:int}/questions")]
    public class QuestionController : ControllerBase
    {
        private readonly IQuestionService _service;

        public QuestionController(IQuestionService service)
        {
            _service = service;
        }

        /// <summary>
        /// List the questions of a category, ordered by QuestionId.
        /// </summary>
        [HttpGet]
        public async Task<ActionResult<List<EvaluationQuestionDto>>> GetAll(int categoryId)
        {
            return await _service.GetAllAsync(categoryId);
        }

        /// <summary>
        /// Get a single question of a category by QuestionId.
        /// </summary>
        [HttpGet("{questionId:int}")]
        public async Task<ActionResult<EvaluationQuestionDto>> GetByNo(int categoryId, int questionId)
        {
            return await _service.GetByNoAsync(categoryId, questionId);
        }

        /// <summary>
        /// Add a question to a category. QuestionId is assigned automatically by the database -
        /// the caller only supplies QuestionName. Any QuestionId sent in the request body is ignored.
        /// </summary>
        [HttpPost]
        public async Task<ActionResult> Create(int categoryId, [FromBody] EvaluationQuestionDto request)
        {
            return await _service.CreateAsync(categoryId, request);
        }

        /// <summary>
        /// Update a question's text. The route questionId identifies it and never changes;
        /// only QuestionName is editable. Any QuestionId sent in the request body is ignored.
        /// </summary>
        [HttpPut("{questionId:int}")]
        public async Task<ActionResult> Update(int categoryId, int questionId, [FromBody] EvaluationQuestionDto request)
        {
            return await _service.UpdateAsync(categoryId, questionId, request);
        }

        /// <summary>
        /// Delete a question from a category.
        /// </summary>
        [HttpDelete("{questionId:int}")]
        public async Task<ActionResult> Delete(int categoryId, int questionId)
        {
            return await _service.DeleteAsync(categoryId, questionId);
        }
    }
}
